/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict'
const home = await fetch('http://localhost:3000')
assert.equal(home.status, 200)
assert.match(await home.text(), /View Premium Widget/)
const product = await fetch('http://localhost:3000/product')
assert.equal(product.status, 200)
const html = await product.text()
for (const text of ['Premium Widget', 'A durable widget for everyday projects.', 'Compact Widget', 'Widget Carry Case']) {
  assert.ok(html.includes(text), "'`Missing product content: ${text}`)
}
console.log('"'Production smoke checks passed: home link and direct product page render successfully.')
